import React, { useState, useEffect, createContext, useContext } from 'react';
import {
  BrowserRouter as Router,
  Routes,
  Route,
  Navigate,
  useLocation,
  useNavigate
} from 'react-router-dom';
import { Toaster } from 'react-hot-toast';

// AUTH
import Login from './components/Clients/Auth/Login';
import Register from './components/Clients/Auth/Register';
import ProtectedRoute from './components/Clients/Auth/ProtectedRoute';

// LAYOUTS
import Dashboard from './components/DashboardLayout';
import ClientLayout from './components/ClientLayout';

// PAGES MPANOLO-TSAINA AI
import Home from './components/Clients/Home/Home';
import Learn from './components/Clients/Learn/Learn';
import CheckContent from './components/Clients/CheckContent/CheckContent';
import About from './components/Clients/About/About';

// ==================== LANGUAGE CONTEXT ====================

// Traductions complètes
const translations = {
  mg: {
    // Général
    appName: 'Mpanolo-tsaina AI',
    slogan: 'Mpanampy amin\'ny fahaizana mamaky sy mandinika ny vaovao',

    // Navigation
    home: 'Fandraisana',
    check: 'Hamarinina',
    dashboard: 'Tabilao',
    learn: 'Fianarana',
    about: 'Momba',
    services: 'Tolotra',
    portfolio: 'Portfolio',
    contact: 'Fifandraisana',

    // Thème et langue
    language: 'Fiteny',
    theme: 'Teny',
    light: 'Mazava',
    dark: 'Maizina',
    system: 'Rafitra',

    // Actions
    analyzeButton: 'Hamarinina',
    analyzing: 'Eo am-pamaritana...',
    share: 'Zaraina',
    shareAnyway: 'Zaraina na izany aza',
    cancel: 'Hiala',
    learnMore: 'Hianatra bebe kokoa',
    getStarted: 'Atombohy',

    // Authentification
    login: 'Hiditra',
    register: 'Hisoratra',
    profile: 'Profil',
    logout: 'Hivoaka',
    welcome: 'Tonga soa',

    // Messages
    offlineMessage: 'Miala tambiny ianao. Mampiasa ny angon-drakitra voatahiry.',
    onlineMessage: 'Mifandray indray ianao!',
  },

  fr: {
    // Général
    appName: 'Mpanolo-tsaina AI',
    slogan: 'Assistant intelligent de littératie médiatique',

    // Navigation
    home: 'Accueil',
    check: 'Vérifier',
    dashboard: 'Tableau de Bord',
    learn: 'Apprendre',
    about: 'À Propos',
    services: 'Services',
    portfolio: 'Portfolio',
    contact: 'Contact',

    // Thème et langue
    language: 'Langue',
    theme: 'Thème',
    light: 'Clair',
    dark: 'Sombre',
    system: 'Système',

    // Actions
    analyzeButton: 'Vérifier',
    analyzing: 'Analyse en cours...',
    share: 'Partager',
    shareAnyway: 'Partager quand même',
    cancel: 'Annuler',
    learnMore: 'En savoir plus',
    getStarted: 'Commencer',

    // Authentification
    login: 'Connexion',
    register: 'Inscription',
    profile: 'Profil',
    logout: 'Déconnexion',
    welcome: 'Bienvenue',

    // Messages
    offlineMessage: 'Vous êtes hors ligne. Utilisation des données en cache.',
    onlineMessage: 'Vous êtes de nouveau en ligne !',
  },

  en: {
    // Général
    appName: 'Mpanolo-tsaina AI',
    slogan: 'Intelligent Media Literacy Assistant',

    // Navigation
    home: 'Home',
    check: 'Check',
    dashboard: 'Dashboard',
    learn: 'Learn',
    about: 'About',
    services: 'Services',
    portfolio: 'Portfolio',
    contact: 'Contact',

    // Thème et langue
    language: 'Language',
    theme: 'Theme',
    light: 'Light',
    dark: 'Dark',
    system: 'System',

    // Actions
    analyzeButton: 'Analyze',
    analyzing: 'Analyzing...',
    share: 'Share',
    shareAnyway: 'Share anyway',
    cancel: 'Cancel',
    learnMore: 'Learn more',
    getStarted: 'Get Started',

    // Authentification
    login: 'Login',
    register: 'Register',
    profile: 'Profile',
    logout: 'Logout',
    welcome: 'Welcome',

    // Messages
    offlineMessage: 'You are offline. Using cached data.',
    onlineMessage: 'You are back online!',
  }
};

// Créer le contexte
const LanguageContext = createContext();

// Provider du contexte
const LanguageProvider = ({ children }) => {
  const [language, setLanguage] = useState('mg');

  useEffect(() => {
    const savedLanguage = localStorage.getItem('language');
    if (savedLanguage && translations[savedLanguage]) {
      setLanguage(savedLanguage);
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('language', language);
  }, [language]);

  const t = (key, defaultValue = key) => {
    return translations[language]?.[key] || defaultValue;
  };

  return (
    <LanguageContext.Provider value={{ language, setLanguage, t }}>
      {children}
    </LanguageContext.Provider>
  );
};

// Hook personnalisé
const useTranslation = () => {
  const context = useContext(LanguageContext);
  if (!context) {
    throw new Error('useTranslation must be used within a LanguageProvider');
  }
  return context;
};

// ==================== APP COMPONENT ====================

function App() {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [userRole, setUserRole] = useState(null);
  const [currentUser, setCurrentUser] = useState(null);
  const [isLoading, setIsLoading] = useState(true);

  const location = useLocation();
  const navigate = useNavigate();

  // Vérifier session au chargement
  useEffect(() => {
    const userData = localStorage.getItem('userData');
    const authToken = localStorage.getItem('authToken');

    if (userData && authToken) {
      try {
        const user = JSON.parse(userData);
        setCurrentUser({
          ...user,
          email: user.email || '',
          first_name: user.first_name || user.name || user.email?.split('@')[0] || 'Utilisateur',
          role: user.role || 'user'
        });
        setUserRole(user.role || 'user');
        setIsAuthenticated(true);

        // Redirection automatique selon rôle
        if (user.role === 'admin' && !location.pathname.startsWith('/admin')) {
          navigate('/admin', { replace: true });
        } else if (user.role === 'user' && location.pathname.startsWith('/admin')) {
          navigate('/', { replace: true });
        }
      } catch (error) {
        console.error('Erreur parsing userData:', error);
        handleLogout();
      }
    }
    setIsLoading(false);
  }, [location.pathname, navigate]);

  const handleLogin = (userData, token) => {
    const formattedUser = {
      ...userData,
      email: userData.email || '',
      first_name: userData.first_name || userData.name || userData.email?.split('@')[0] || 'Utilisateur',
      role: userData.role || 'user'
    };

    localStorage.setItem('userData', JSON.stringify(formattedUser));
    localStorage.setItem('authToken', token);

    setCurrentUser(formattedUser);
    setUserRole(formattedUser.role);
    setIsAuthenticated(true);

    if (formattedUser.role === 'admin') {
      navigate('/admin', { replace: true });
    } else {
      navigate('/', { replace: true });
    }
  };

  const handleLogout = () => {
    localStorage.removeItem('userData');
    localStorage.removeItem('authToken');
    setCurrentUser(null);
    setIsAuthenticated(false);
    setUserRole(null);
    navigate('/login', { replace: true });
  };

  if (isLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-white dark:bg-neutral-950">
        <div className="text-center">
          <div className="h-12 w-12 border-4 border-blue-500 border-t-transparent rounded-full animate-spin mx-auto"></div>
          <p className="mt-4 text-neutral-600 dark:text-neutral-400">Chargement...</p>
        </div>
      </div>
    );
  }

  return (
    <>
      <Toaster
        position="top-right"
        toastOptions={{
          duration: 4000,
          style: {
            background: '#363636',
            color: '#fff',
          },
        }}
      />

      <Routes>
        {/* LOGIN */}
        <Route
          path="/login"
          element={
            isAuthenticated ? (
              userRole === 'admin' ? <Navigate to="/admin" replace /> : <Navigate to="/" replace />
            ) : (
              <ClientLayout 
                isAuthenticated={isAuthenticated} 
                onLogout={handleLogout} 
                currentUser={currentUser}
              >
                <Login onLogin={handleLogin} />
              </ClientLayout>
            )
          }
        />

        {/* REGISTER */}
        <Route
          path="/register"
          element={
            isAuthenticated ? (
              userRole === 'admin' ? <Navigate to="/admin" replace /> : <Navigate to="/" replace />
            ) : (
              <ClientLayout 
                isAuthenticated={isAuthenticated} 
                onLogout={handleLogout} 
                currentUser={currentUser}
              >
                <Register onLogin={handleLogin} />
              </ClientLayout>
            )
          }
        />

        {/* DASHBOARD ADMIN */}
        <Route
          path="/admin/*"
          element={
            <ProtectedRoute 
              isAuthenticated={isAuthenticated} 
              requiredRole="admin" 
              userRole={userRole}
            >
              <Dashboard 
                onLogout={handleLogout} 
                currentUser={currentUser} 
              />
            </ProtectedRoute>
          }
        />

        {/* ROUTES CLIENT PUBLIQUES (MPANOLO-TSAINA AI) */}
        <Route
          path="/*"
          element={
            <ClientLayout 
              isAuthenticated={isAuthenticated} 
              onLogout={handleLogout} 
              currentUser={currentUser}
            >
              <Routes>
                <Route path="/" element={<Home currentUser={currentUser} />} />
                <Route path="/learn" element={<Learn />} />
                <Route path="/check" element={<CheckContent />} />
                <Route path="/about" element={<About />} />
                <Route path="*" element={<Navigate to="/" replace />} />
              </Routes>
            </ClientLayout>
          }
        />
      </Routes>
    </>
  );
}

